"""The add-in manifest of this instance, and the demo mails for the browser preview."""
import uuid
from urllib.parse import urlparse
from xml.sax.saxutils import escape

from werkzeug.exceptions import Forbidden

from odoo import http
from odoo.http import request

ADDIN_ID_PARAM = "vme_mail_plugin.addin_id"
STATIC = "/vme_mail_plugin/static/outlook"

MANIFEST = """<?xml version="1.0" encoding="UTF-8"?>
<!-- Outlook add-in of {base_url} (database {db}). Generated by Odoo: every instance hands out its own. -->
<OfficeApp xmlns="http://schemas.microsoft.com/office/appforoffice/1.1"
           xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
           xmlns:bt="http://schemas.microsoft.com/office/officeappbasictypes/1.0"
           xmlns:mailappor="http://schemas.microsoft.com/office/mailappversionoverrides/1.0"
           xsi:type="MailApp">
  <Id>{addin_id}</Id>
  <Version>1.0.0.0</Version>
  <ProviderName>Quotis</ProviderName>
  <DefaultLocale>nl-NL</DefaultLocale>
  <DisplayName DefaultValue="{name}"/>
  <Description DefaultValue="Toont bij een mail de VME, de kavel en wat er openstaat, met het voorstel van de AI-assistent."/>
  <IconUrl DefaultValue="{base_url}{static}/icon-64.png"/>
  <HighResolutionIconUrl DefaultValue="{base_url}{static}/icon-128.png"/>
  <SupportUrl DefaultValue="{base_url}"/>
  <AppDomains>
    <AppDomain>{base_url}</AppDomain>
  </AppDomains>
  <Hosts>
    <Host Name="Mailbox"/>
  </Hosts>
  <Requirements>
    <Sets>
      <Set Name="Mailbox" MinVersion="1.1"/>
    </Sets>
  </Requirements>
  <FormSettings>
    <Form xsi:type="ItemRead">
      <DesktopSettings>
        <SourceLocation DefaultValue="{base_url}{static}/taskpane.html?v={version}"/>
        <RequestedHeight>450</RequestedHeight>
      </DesktopSettings>
    </Form>
  </FormSettings>
  <Permissions>ReadItem</Permissions>
  <Rule xsi:type="RuleCollection" Mode="Or">
    <Rule xsi:type="ItemIs" ItemType="Message" FormType="Read"/>
  </Rule>
  <DisableEntityHighlighting>false</DisableEntityHighlighting>
  <VersionOverrides xmlns="http://schemas.microsoft.com/office/mailappversionoverrides" xsi:type="VersionOverridesV1_0">
    <VersionOverrides xmlns="http://schemas.microsoft.com/office/mailappversionoverrides/1.1" xsi:type="VersionOverridesV1_1">
      <Requirements>
        <bt:Sets DefaultMinVersion="1.5">
          <bt:Set Name="Mailbox"/>
        </bt:Sets>
      </Requirements>
      <Hosts>
        <Host xsi:type="MailHost">
          <DesktopFormFactor>
            <FunctionFile resid="Commands.Url"/>
            <ExtensionPoint xsi:type="MessageReadCommandSurface">
              <OfficeTab id="TabDefault">
                <Group id="vmeReadGroup">
                  <Label resid="Group.Label"/>
                  <Control xsi:type="Button" id="vmeOpenPane">
                    <Label resid="Button.Label"/>
                    <Supertip>
                      <Title resid="Button.Label"/>
                      <Description resid="Button.Tooltip"/>
                    </Supertip>
                    <Icon>
                      <bt:Image size="16" resid="Icon.16"/>
                      <bt:Image size="32" resid="Icon.32"/>
                      <bt:Image size="80" resid="Icon.80"/>
                    </Icon>
                    <Action xsi:type="ShowTaskpane">
                      <SourceLocation resid="Taskpane.Url"/>
                      <SupportsPinning>true</SupportsPinning>
                    </Action>
                  </Control>
                </Group>
              </OfficeTab>
            </ExtensionPoint>
          </DesktopFormFactor>
        </Host>
      </Hosts>
      <Resources>
        <bt:Images>
          <bt:Image id="Icon.16" DefaultValue="{base_url}{static}/icon-16.png"/>
          <bt:Image id="Icon.32" DefaultValue="{base_url}{static}/icon-32.png"/>
          <bt:Image id="Icon.80" DefaultValue="{base_url}{static}/icon-80.png"/>
        </bt:Images>
        <bt:Urls>
          <bt:Url id="Commands.Url" DefaultValue="{base_url}{static}/commands.html"/>
          <bt:Url id="Taskpane.Url" DefaultValue="{base_url}{static}/taskpane.html?v={version}"/>
        </bt:Urls>
        <bt:ShortStrings>
          <bt:String id="Group.Label" DefaultValue="{name}"/>
          <bt:String id="Button.Label" DefaultValue="VME-dossier"/>
        </bt:ShortStrings>
        <bt:LongStrings>
          <bt:String id="Button.Tooltip" DefaultValue="Toon de VME, de kavel en het voorstel van de AI-assistent bij deze mail."/>
        </bt:LongStrings>
      </Resources>
    </VersionOverrides>
  </VersionOverrides>
</OfficeApp>
"""


def addin_id(env):
    """A fixed id per database, so a new manifest replaces the add-in instead of adding a second one."""
    params = env["ir.config_parameter"].sudo()
    value = params.get_param(ADDIN_ID_PARAM)
    if not value:
        value = str(uuid.uuid4())
        params.set_param(ADDIN_ID_PARAM, value)
    return value


def render_manifest(env):
    base_url = env["vme.mail.context"]._vme_mail_base_url()
    return MANIFEST.format(
        base_url=escape(base_url), static=STATIC, db=escape(env.cr.dbname), addin_id=addin_id(env),
        name=escape(f"VME-dossier ({urlparse(base_url).hostname or env.cr.dbname})"[:125]),
        version=escape(env["ir.module.module"].sudo().search([("name", "=", "vme_mail_plugin")]).latest_version or "1"),
    )


class VmeMailPluginManifest(http.Controller):

    @http.route("/vme_mail_plugin/manifest.xml", type="http", auth="user", methods=["GET"])
    def manifest(self, **kwargs):
        if not request.env.user._is_internal():
            raise Forbidden()
        return request.make_response(render_manifest(request.env), headers=[
            ("Content-Type", "application/xml; charset=utf-8"),
            ("Content-Disposition", 'attachment; filename="vme-outlook-manifest.xml"'),
        ])

    @http.route("/vme_mail_plugin/demo/inbox", type="jsonrpc", auth="user")
    def demo_inbox(self, **kwargs):
        """The fictitious mails for taskpane.html?demo=1; for administrators or in debug mode."""
        if not (request.env.user.has_group("base.group_system") or request.session.debug):
            raise Forbidden()
        return {"mails": request.env["vme.mail.context"]._vme_mail_demo_inbox()}
